// https://github.com/epibyte/p5-epi-colors
const { EpiColors } = EpiColorsPckg;
let epiColors;

function setup() {
	createCanvas(S=~~(min(innerWidth, innerHeight)*0.95), S);
	frameRate(30);

	epiColors = new EpiColors();
	epiColors.getRandomPalette(true);

	noiseSeed(~~random(7654321));
	loop();
}

function draw() {
	stroke(EpiColors.getColor(epiColors.BG, 64));
	strokeWeight(1);
	background(epiColors.BG);

	const PAD = S * 0.2;

	for (let y = PAD; y < height + PAD; y += PAD/5) {
		fill(map(y, 0, height, 50, 200))
		const f = map(y, PAD, height+PAD, 0, 1);
		// const clr = lerpColor(epiColors.palette[0], epiColors.palette[1], 1-f);
		const clr = epiColors.getLerpedColorFromPalette(f/2); // just use half of palette
		fill(clr);

		beginShape();
		vertex(0, height+y);

		const ny = noise(5 * y / height);
		const cx = ny * width;
		// console.log(ny)
		for (let x = 0; x < width; x += width * 0.01) {
			const a = map(x, 0, width, HALF_PI, TWO_PI + HALF_PI) + (ny-0.5)*4;
			const n = noise(x / width * 10, y / height * 10, frameCount/1500);
			const d = map(abs(cx - x), 0, width, 1, 0.1)
			const yy = sin(a) * S/4 * n /* * d */ + y;
			vertex(x, yy);
		}

		vertex(width, height+y);
		endShape();
	}

	strokeWeight(8);
	stroke(epiColors.FG);
	noFill();
	rect(4, 4, width-8, height-8);

	// noLoop();
}

function mousePressed() {
	if (mouseButton.left && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
